(1, 'dr-ipshita-johri', 'Dr. Ipshita Johri', 'Founder, Medical Director & Chief Dermatologist', 'MBBS, DDV | PG Dip. Clinical Dermatology (Cardiff University, U.K.)', 'Celebrity Dermatologist, Advanced Anti-Ageing, Facial Sculpting & Aesthetic Lasers', '12+ Years Clinical Experience', '/images/doctors/dr-ipshita-johri.webp', NULL, 'Dr. Ipshita Johri is the visionary founder and medical director of Skinfinity Derma clinics in Noida and Gurgaon. An internationally trained clinical dermatologist holding prestigious credentials from Cardiff University UK, she is renowned for her holistic, root-cause aesthetic medical approach.', NULL, NULL, NULL, NULL, 1200, '[\"Noida\",\"Gurgaon\"]', 'Mon, Wed, Fri, Sat (10:00 AM - 07:00 PM)', 1, 1, '2026-10-26 18:07:04', '2026-11-01 12:19:04'),
(2, 'dr-sukriti-agarwal', 'Dr. Sukriti Agarwal', 'Senior Consultant Dermatologist & Trichologist', 'MBBS, MD - Dermatology, Venereology & Leprosy', 'Acne Scar Subcision, Chemical Peels, Melasma Revision & Laser Hair Reduction', '8+ Years Clinical Experience', '/images/doctors/dr-sukriti-agarwal.webp', NULL, 'Dr. Sukriti Agarwal is an acclaimed board-certified MD dermatologist specializing in clinical dermatology, medical trichology and scar revision protocols.', NULL, NULL, NULL, NULL, 1000, '[\"Noida\"]', 'Mon - Sat (10:30 AM - 06:30 PM)', 2, 1, '2026-10-26 18:07:04', '2026-11-01 12:13:17'),
