(9, 'offer-1', 'Body Wellness & Rejuvenation Packages', 'Limited Period', 'Body', 'Holistic full body therapies, skin detox, and clinical body polishing supervised by senior medical experts.', '/images/offers/body-wellness-packages.png', 'Claim Offer', '/contact-us#appointment_form', NULL, NULL, NULL, 1, 1, '2026-11-05 14:19:12', '2026-11-05 14:19:12'),
(10, 'offer-2', 'Bridal Skin Preparation Luxury Package', 'Bridal Special', 'Bridal', 'Curated pre-bridal skin brightening, hydrafacial, and glow sessions tailored for brides-to-be.', '/images/offers/bridal-skin-preparation-package.png', 'Book Bridal Package', '/contact-us#appointment_form', NULL, NULL, NULL, 2, 1, '2026-11-05 14:19:12', '2026-11-05 14:19:12'),
(11, 'offer-3', 'Special Bridal Luxury Packages', 'Bridal Glow', 'Bridal', 'Head-to-toe bridal aesthetics, laser smoothing, and luminous facials for weddings.', '/images/offers/special-bridal-packages.png', 'Explore Packages', '/contact-us#appointment_form', NULL, NULL, NULL, 3, 1, '2026-11-05 14:19:12', '2026-11-05 14:19:12'),
(12, 'offer-4', 'Medical Facial Offers', 'Instant Glow', 'Skin', 'Special prices on clinical medi-facials, carbon peel, and deep pore cleansing protocols.', '/images/offers/facial-offers.png', 'Claim Offer', '/contact-us#appointment_form', NULL, NULL, NULL, 4, 1, '2026-11-05 14:19:12', '2026-11-05 14:19:12'),
(13, 'offer-5', 'Signature Facial Packages', 'Radiance Care', 'Skin', 'Exclusive bundled facial packages designed for long-lasting hydration, elasticity, and radiance.', '/images/offers/facial-packages.png', 'Claim Package', '/contact-us#appointment_form', NULL, NULL, NULL, 5, 1, '2026-11-05 14:19:12', '2026-11-05 14:19:12'),
(14, 'offer-6', 'Fat Loss & Skin Tightening Treatment Plan', 'Body Contouring', 'Body', 'Non-invasive body contouring, fat reduction, and ultrasound/RF skin tightening plans.', '/images/offers/fat-loss-and-skin-tightening-treatment-plan.png', 'Consult Specialist', '/contact-us#appointment_form', NULL, NULL, NULL, 6, 1, '2026-11-05 14:19:12', '2026-11-05 14:19:12'),
(15, 'offer-7', 'Festive Hair Care Packages', 'Festive Deal', 'Hair', 'Strengthen roots and restore natural shine with multi-session medical hair therapies.', '/images/offers/festive-hair-packages.png', 'Claim Hair Offer', '/contact-us#appointment_form', NULL, NULL, NULL, 7, 1, '2026-11-05 14:19:12', '2026-11-05 14:19:12'),
(16, 'offer-8', 'Skinfinity All-In-One Festive Package', 'Limited Edition', 'Skin', 'Complete all-in-one festive skin rejuvenation package for picture-perfect results.', '/images/offers/festive-package.png', 'Claim Festive Deal', '/contact-us#appointment_form', NULL, NULL, NULL, 8, 1, '2026-11-05 14:19:12', '2026-11-05 14:19:12'),
(17, 'offer-9', 'Dermal Fillers Festive Packages', 'Anti-Ageing', 'Skin', 'US-FDA approved hyaluronic fillers for volume restoration, smile lines, and lip definition.', '/images/offers/fillers-festive-packages.png', 'Book Consultation', '/contact-us#appointment_form', NULL, NULL, NULL, 9, 1, '2026-11-05 14:19:12', '2026-11-05 14:19:12'),
(18, 'offer-10', 'Dermal Fillers Special Offers', 'Aesthetic Special', 'Skin', 'Doctor-led natural facial contouring with premium dermal fillers at special festive pricing.', '/images/offers/fillers-offers.png', 'Claim Offer', '/contact-us#appointment_form', NULL, NULL, NULL, 10, 1, '2026-11-05 14:19:12', '2026-11-05 14:19:12'),
(19, 'offer-11', 'Premium Dermal Fillers Packages', 'Youthful Lift', 'Skin', 'Customized multi-syringe filler packages with senior aesthetic injectors.', '/images/offers/fillers-packages.png', 'Explore Fillers', '/contact-us#appointment_form', NULL, NULL, NULL, 11, 1, '2026-11-05 14:19:12', '2026-11-05 14:19:12'),
(20, 'offer-12', 'GFC Therapy Festive Offer', 'Hair Regrowth', 'Hair', 'Growth Factor Concentrate (GFC) therapy for advanced hair fall stoppage and density boost.', '/images/offers/gfc-festive-offer.png', 'Claim GFC Offer', '/contact-us#appointment_form', NULL, NULL, NULL, 12, 1, '2026-11-05 14:19:12', '2026-11-05 14:19:12'),
(21, 'offer-13', 'Hair Fall Control Festive Packages', 'Root Defense', 'Hair', 'Combined medical trichology sessions, mesotherapy, and scalp detox for acute hair shedding.', '/images/offers/hair-fall-festive-packages.png', 'Stop Hair Fall', '/contact-us#appointment_form', NULL, NULL, NULL, 13, 1, '2026-11-05 14:19:12', '2026-11-05 14:19:12'),
(22, 'offer-14', 'Hair Regain Booster Festival Offer', 'Cellular Boost', 'Hair', 'Advanced cellular hair regain booster therapy delivering micro-nutrients to dormant follicles.', '/images/offers/hair-regain-booster-festival-offer.png', 'Claim Booster Offer', '/contact-us#appointment_form', NULL, NULL, NULL, 14, 1, '2026-11-05 14:19:12', '2026-11-05 14:19:12'),
(23, 'offer-15', 'Hair Regain Booster Exclusive Offers', 'Popular Deal', 'Hair', 'Accelerate hair growth and volume with specialized booster sessions.', '/images/offers/hair-regain-booster-offers.png', 'Claim Deal', '/contact-us#appointment_form', NULL, NULL, NULL, 15, 1, '2026-11-05 14:19:12', '2026-11-05 14:19:12'),
(24, 'offer-16', 'Hair Regain Booster Multi-Session Packages', 'Best Value', 'Hair', 'Comprehensive 4 to 6 session hair regain booster program for sustained density.', '/images/offers/hair-regain-booster-packages.png', 'View Packages', '/contact-us#appointment_form', NULL, NULL, NULL, 16, 1, '2026-11-05 14:19:12', '2026-11-05 14:19:12'),
(25, 'offer-17', 'US-FDA Laser Festive Offer', 'Laser Special', 'Laser', 'Painless triple-wavelength laser sessions for smooth, hair-free skin with contact cooling.', '/images/offers/laser-festive-offer.png', 'Claim Laser Offer', '/contact-us#appointment_form', NULL, NULL, NULL, 17, 1, '2026-11-05 14:19:12', '2026-11-05 14:19:12'),
(26, 'offer-18', 'Laser Hair Reduction Festive Packages', 'Painless ICE', 'Laser', 'Full body and combo laser hair removal packages with permanent follicle reduction.', '/images/offers/laser-festive-packages.png', 'Claim Package', '/contact-us#appointment_form', NULL, NULL, NULL, 18, 1, '2026-11-05 14:19:12', '2026-11-05 14:19:12'),
(27, 'offer-19', 'Laser Hair Reduction Festival Offer', 'Zero Downtime', 'Laser', 'Limited-period promotional rates on Soprano Titanium laser hair reduction sessions.', '/images/offers/laser-hair-reduction-festival-offer.png', 'Book Session', '/contact-us#appointment_form', NULL, NULL, NULL, 19, 1, '2026-11-05 14:19:12', '2026-11-05 14:19:12');
