(1, 'About Skinfinity Derma Clinics', 'about-us', 'Physician-Led Medical Aesthetics & Dermatology', '/images/custom/clinic-reception.jpg', 'Skinfinity Derma is a premier healthcare institution providing advanced dermatology, trichology, and aesthetic treatments in Noida and Gurugram.', NULL, NULL, NULL, 1, 0, '2026-11-01 09:05:45', '2026-11-01 09:05:45'),
(2, 'Medical Clinic Infrastructure', 'about-clinic', 'US-FDA Approved Laser Suite & On-Site Pathology', '/images/custom/clinic-reception.jpg', 'Our clinics are designed according to NABH standards with temperature-controlled sterile procedure suites and private consultation lounges.', NULL, NULL, NULL, 1, 0, '2026-11-01 09:05:45', '2026-11-01 09:05:45'),
(3, 'Aesthetic Clinic Franchise Opportunities', 'franchise', 'Turnkey Business Model with Complete Medical Guidance', '/images/custom/clinic-reception.jpg', 'Partner with Skinfinity Derma to establish high-return aesthetic clinics in major metro hubs.', NULL, NULL, NULL, 1, 0, '2026-11-01 09:05:45', '2026-11-01 09:05:45'),
(4, 'VIP Privilege Club Membership', 'membership', 'Exclusive Year-Round Dermatology Perks & Discounts', '/images/custom/clinic-reception.jpg', 'Unlock complimentary sessions, priority doctor bookings, and flat discounts on all clinical therapies.', NULL, NULL, NULL, 1, 0, '2026-11-01 09:05:45', '2026-11-01 09:05:45'),
(5, 'Contact Skinfinity Derma Clinics', 'contact-us', 'Noida Sector 36 & Gurugram Sector 28', '/images/custom/clinic-reception.jpg', 'Reach our patient care desk for priority appointments, consultation questions, or directions.', NULL, NULL, NULL, 1, 0, '2026-11-01 09:05:45', '2026-11-01 09:05:45');
