INSERT INTO `sid_patient_consultations` (`id`, `patient_id`, `appointment_id`, `doctor_id`, `clinic_id`, `consultation_date`, `primary_concern`, `symptoms`, `skin_hair_assessment`, `diagnosis`, `treatment_recommendations`, `doctor_notes`, `follow_up_date`, `status`, `created_at`, `updated_at`) VALUES
(1, 3, NULL, 1, 1, '2026-10-15', 'Hormonal Cystic Acne on Chin & Jawline', 'Painful inflamed papules, flares pre-menstruation', 'Fitzpatrick IV. Sebum index 82. Inflammatory acne lesions (Grade 3).', 'Hormonal Acne Vulgaris with Post-Inflammatory Erythema', 'Salicylic acid peel 20\%, Topical Clindamycin + Nicotinamide gel, Soprano Titanium laser patch test.', 'Patient advised low glycemic diet. Mandatory broad-spectrum tinted mineral SPF 50.', '2026-11-15', 'Completed', '2026-11-05 18:17:00', '2026-11-05 18:17:00'),
(2, 5, NULL, 2, 2, '2026-10-20', 'Crown & Hairline Thinning', 'Excessive hair shed during shower (>100 hairs/day), widening parting line', 'Dermascope scalp examination shows >20\% hair miniaturization at frontal & mid-scalp. Negative pull test on occipital zone.', 'Androgenetic Alopecia (Norwood Grade 3)', '3 sessions of autologous GFC (Growth Factor Concentrate) mesotherapy + Scalp microneedling at 1.2mm depth.', 'Explained autologous blood centrifugation process. Prescribed daily Procapil & Redensyl serum.', '2026-11-20', 'Completed', '2026-11-05 18:17:00', '2026-11-05 18:17:00'),
(3, 6, NULL, 1, 1, '2026-10-24', 'Cheek Pigmentation & Sun Spots', 'Brown patches on cheekbones worsening post-sun exposure', 'Wood lamp examination confirms epidermal melasma with scattered solar lentigines. Healthy skin barrier.', 'Bilateral Epidermal Melasma & Photo-damage', 'Q-Switched Nd:YAG Laser Toning (1064nm low fluence) combined with Sugarcane HydraFacial MD.', 'Strict broad-spectrum PA++++ sunscreen reapplication every 3 hours.', '2026-11-24', 'Completed', '2026-11-05 18:17:00', '2026-11-05 18:17:00'),
(4, 7, NULL, 1, 1, '2026-10-28', 'Deep Boxcar & Rolling Acne Scars', 'Indented craters on bilateral cheeks since age 19', 'Severe tethered dermal fibrotic bands causing visible dimpling under tangential light.', 'Grade 3 Atrophic Boxcar & Rolling Acne Scars', 'Blunt Cannula Subcision followed immediately by Secret RF Microneedling (depth 2.0mm).', 'Patient consented to procedure. Post-treatment mild edema expected for 48 hours.', '2026-11-28', 'Completed', '2026-11-05 18:17:00', '2026-11-05 18:17:00');
INSERT INTO `sid_patient_documents` (`id`, `patient_id`, `consultation_id`, `document_type`, `document_name`, `file_url`, `file_size`, `file_mime`, `notes`, `uploaded_by`, `created_at`) VALUES
(1, 3, NULL, 'Lab Report', 'Hormonal Profile & Thyroid Panel (TSH, Free Testosterone, DHEAS)', '/documents/lab-hormones-101.pdf', 342100, 'application/pdf', 'Elevated Free Testosterone correlating with chin acne flare.', 1, '2026-11-05 18:17:00'),
(2, 3, NULL, 'Skin Analysis', 'Skinfinity 3D Facial Dermascan Topology Report', '/documents/dermascan-101.pdf', 812900, 'application/pdf', 'High sebum secretion score (84/100), moderate dermal redness.', 1, '2026-11-05 18:17:00'),
(3, 5, NULL, 'Trichoscopy Report', 'Digital Scalp Trichogram & Follicular Unit Count', '/documents/trichogram-102.pdf', 542000, 'application/pdf', 'Hair density: 142 hairs/cm2 in crown, miniaturization ratio 22\%.', 2, '2026-11-05 18:17:00'),
(4, 7, NULL, 'Treatment Consent', 'Cannula Subcision & RF Microneedling Informed Consent Form', '/documents/consent-subcision-104.pdf', 215000, 'application/pdf', 'Signed medical informed consent on file.', 1, '2026-11-05 18:17:00');
INSERT INTO `sid_patient_gallery` (`id`, `patient_id`, `treatment_id`, `appointment_id`, `before_image_url`, `after_image_url`, `title`, `description`, `session_date`, `is_private`, `created_at`) VALUES
(1, 3, 69, NULL, '/images/before-after/acne-before.png', '/images/before-after/acne-after.png', 'Cheek & Jawline Active Acne Resolution', 'Marked reduction in inflammatory papules and erythema after 3 chemical peels & clinical skincare protocol.', '2026-10-15', 1, '2026-11-05 18:17:00'),
(2, 5, 4, NULL, '/images/before-after/hair-before.png', '/images/before-after/hair-after.png', 'Crown Hair Regrowth after 2 GFC Sessions', 'Noticeable thickening and follicular density enhancement along mid-scalp parting.', '2026-10-20', 1, '2026-11-05 18:17:00'),
(3, 6, 71, NULL, '/images/before-after/pigment-before.png', '/images/before-after/pigment-after.png', 'Malar Melasma Lightening', 'Significant 60\% lightening of epidermal hyperpigmentation following low-fluence Q-Switch laser toning.', '2026-10-24', 1, '2026-11-05 18:17:00');
