INSERT INTO `sid_patient_prescriptions` (`id`, `prescription_no`, `patient_id`, `doctor_id`, `consultation_id`, `clinic_id`, `diagnosis`, `general_advice`, `follow_up_date`, `prescription_date`, `created_at`) VALUES
(1, 'RX-2026-1001', 3, 1, NULL, 1, 'Hormonal Acne Vulgaris with Post-Inflammatory Erythema', 'Wash face twice daily with cool water. Do not pick or scratch active papules. Apply sunscreen 20 mins before stepping outdoors.', '2026-11-15', '2026-10-15', '2026-11-05 18:17:00'),
(2, 'RX-2026-1002', 5, 2, NULL, 2, 'Androgenetic Alopecia (Norwood Grade 3)', 'Avoid hot water showers on scalp. Maintain balanced protein intake. No intense scalp scratching for 48h after GFC session.', '2026-11-20', '2026-10-20', '2026-11-05 18:17:00');
INSERT INTO `sid_patient_skin_assessments` (`id`, `patient_id`, `consultation_id`, `doctor_id`, `assessment_date`, `skin_type`, `skin_concerns`, `acne_condition`, `pigmentation`, `melasma`, `skin_sensitivity`, `hair_concerns`, `previous_treatments`, `current_skincare_routine`, `assessment_notes`, `created_at`) VALUES
(1, 3, NULL, 1, '2026-10-15', 'Oily / Combination (Fitzpatrick IV)', 'Acne breakout, open pores, sebum shine', 'Grade 3 Hormonal Papulopustular', 'Post-Inflammatory Hyperpigmentation (PIH)', 'None', 'Moderate (reacts to harsh alcohol cleansers)', 'Mild hair shedding', 'OTC Benzoyl Peroxide gel with peeling', 'Gentle foaming cleanser, Niacinamide 5\% serum, lightweight gel moisturizer', 'Skin barrier slightly dehydrated; focused first on soothing hydration and inflammation control.', '2026-11-05 18:17:00'),
(2, 5, NULL, 2, '2026-10-20', 'Normal to Dry Scalp', 'Scalp thinning, follicle weakening', 'None', 'None', 'None', 'Low', 'Crown thinning, receding temple hairline', 'OTC Minoxidil 5\% for 6 months with intermittent compliance', 'Ketoconazole 2\% shampoo 2x/week, peptide leave-in serum', 'Good donor density at occipital scalp. Excellent candidate for GFC regenerative therapy.', '2026-11-05 18:17:00'),
(3, 6, NULL, 1, '2026-10-24', 'Dry & Sun Damaged (Fitzpatrick IV)', 'Melasma patches, uneven skin tone', 'None', 'Epidermal hyperpigmentation (Malar distribution)', 'Grade 2 Bilateral Melasma', 'Normal', 'None', 'Over-the-counter brightening creams', 'Cream cleanser, Vitamin C serum 10\%, Hyaluronic Acid, SPF 50+', 'Melasma responding to gentle low-energy laser toning sessions.', '2026-11-05 18:17:00'),
(4, 7, NULL, 1, '2026-10-28', 'Thick Oily Sebaceous Skin', 'Atrophic acne scarring, enlarged pores', 'Quiescent (No active cysts)', 'PIE reddish scar marks', 'None', 'Resilient', 'None', 'Oral Isotretinoin completed in 2023', 'Gentle foaming cleanser, BHA 2\% liquid 1x weekly, ceramides barrier cream', 'Deep scar fibrotic tethering requires manual blunt cannula subcision releases.', '2026-11-05 18:17:00');
