INSERT INTO `sid_reviews` (`id`, `legacy_id`, `reviewer_name`, `initials`, `avatar`, `rating`, `review_text`, `treatment_tag`, `branch`, `source`, `verified`, `review_date`, `display_order`, `is_active`, `created_at`, `updated_at`) VALUES
(1, 'rev-1', 'Sirjana Grewal', 'SG', NULL, 5, 'I have been getting Laser hair removal from here. Great services and hygiene has been consistently maintained throughout the duration of my entire process here. I would blindly recommend this to anyone. Getting laser removal from here has been one of the best decisions I have ever made.', 'Laser Hair Removal', 'Noida HQ Clinic', 'google', 1, '2026-02-10', 1, 1, '2026-10-26 18:07:04', '2026-10-26 18:07:04'),
(2, 'rev-2', 'Kavita Sharma', 'KS', NULL, 5, 'My dermatology visit with Dr. Ipshita\'s clinic exceeded all my expectations. Not only did I leave with a clear understanding of my skin concerns, but I also felt empowered to take control of my skincare regimen. Truly exceptional team!', 'Acne Scar Revision', 'Noida HQ Clinic', 'google', 1, '2026-02-12', 2, 1, '2026-10-26 18:07:04', '2026-10-26 18:07:04'),
(3, 'rev-3', 'Rohan Malhotra', 'RM', NULL, 5, 'Took 3 sessions of GFC for acute hair thinning. The density improvement on my crown within 2 months has been unbelievable. Very transparent and medical-grade approach without any unnecessary products.', 'GFC Hair Regrowth', 'Gurgaon Clinic', 'google', 1, '2026-02-15', 3, 1, '2026-10-26 18:07:04', '2026-10-26 18:07:04'),
(4, 'rev-4', 'Aishwarya Sen', 'AS', NULL, 5, 'The Signature Sugarcane HydraFacial gave my skin an instant glass finish! Zero irritation or redness, and my stubborn blackheads on the nose were completely vacuumed away. Worth every penny.', 'HydraFacial MD', 'Noida HQ Clinic', 'google', 1, '2026-02-18', 4, 1, '2026-10-26 18:07:04', '2026-10-26 18:07:04');
