INSERT INTO `sid_roles` (`id`, `slug`, `name`, `description`, `is_system`, `created_at`, `updated_at`) VALUES
(1, 'super_admin', 'Super Admin', 'Full unrestricted access to all modules, users, roles, system tools, and settings.', 1, '2026-10-26 18:07:03', '2026-11-01 08:16:55'),
(2, 'admin', 'Admin', 'Clinic administration, appointments, patients, catalog, marketing, and operations.', 1, '2026-10-26 18:07:04', '2026-11-01 08:16:55'),
(3, 'seo_executive', 'SEO Executive', 'Owns SEO metadata, sitemap, FAQs and content blocks. Read-only elsewhere.', 1, '2026-10-26 18:07:04', '2026-10-26 18:07:04'),
(4, 'developer', 'Developer', 'Technical owner: site settings, tracking scripts, menus, content blocks, system tools.', 1, '2026-10-26 18:07:04', '2026-10-26 18:07:04'),
(5, 'content_manager', 'Content Manager', 'Manages website content: treatments, blogs, banners, FAQs, gallery, videos, and SEO blocks.', 1, '2026-10-26 18:07:04', '2026-11-01 08:16:55'),
(6, 'front_desk', 'Front Desk', 'Front desk reception (alias for receptionist).', 1, '2026-10-26 18:07:04', '2026-11-01 08:16:55'),
(13, 'clinic_manager', 'Clinic Manager', 'Manages daily clinic operations, appointments calendar, patient profiles, doctors roster, and leads.', 1, '2026-11-01 08:16:16', '2026-11-01 08:16:55'),
(14, 'doctor', 'Doctor', 'Medical board specialist: consultation view, assigned appointments, patient clinical histories, and treatments.', 1, '2026-11-01 08:16:16', '2026-11-01 08:16:55'),
(15, 'receptionist', 'Receptionist', 'Front desk reception: booking patient appointments, rescheduling, check-in, intake of calls and leads.', 1, '2026-11-01 08:16:16', '2026-11-01 08:16:55'),
(16, 'marketing_manager', 'Marketing Manager', 'Manages promotional campaigns: coupons, seasonal offers, hero banners, leads pipeline, and patient reviews.', 1, '2026-11-01 08:16:16', '2026-11-01 08:16:56');
INSERT INTO `sid_seo_pages` (`id`, `path`, `name`, `meta_title`, `meta_description`, `meta_keywords`, `og_title`, `og_description`, `og_image`, `canonical_url`, `robots`, `schema_json`, `include_in_sitemap`, `sitemap_priority`, `sitemap_changefreq`, `is_active`, `created_at`, `updated_at`) VALUES
(1, '/', 'Homepage', 'Best Dermatologist in Noida & Gurgaon | No.1 Skin Clinic | Skinfinity Derma', 'Award-winning Dermatology & Aesthetic Laser clinic led by Dr. Ipshita Johri. 4,500+ Verified reviews with 4.5 Rating. 5 Senior MD Dermatologists.', 'Dermatologist in Noida, Skin specialist Gurgaon, Laser hair removal Noida, HydraFacial Noida, Dr Ipshita Johri', NULL, NULL, '/images/hero/hero-banner.webp', 'https://www.skinfinityderma.com/', 'index,follow', NULL, 1, 1, 'daily', 1, '2026-10-26 18:07:16', '2026-10-26 18:07:16'),
(2, '/treatments', 'Treatments Catalog', 'Dermatology & Laser Treatments in Noida & Gurgaon | Skinfinity Derma', 'Explore full catalog of doctor-led skin, hair, laser, anti-ageing and medi-facial treatments at transparent clinical pricing.', 'Skin treatments price list, Laser hair reduction cost Noida, HydraFacial price Noida, Acne scar doctor', NULL, NULL, NULL, 'https://www.skinfinityderma.com/treatments/', 'index,follow', NULL, 1, 0.9, 'weekly', 1, '2026-10-26 18:07:16', '2026-10-26 18:07:16'),
(3, '/about-clinic', 'About Clinic', 'About Skinfinity Derma Clinic | Vision, Doctors & Technology', 'Learn about Skinfinity Derma’s decade-long medical heritage, founder Dr. Ipshita Johri, and hospital-grade aesthetic care standards.', NULL, NULL, NULL, NULL, 'https://www.skinfinityderma.com/about-clinic/', 'index,follow', NULL, 1, 0.8, 'monthly', 1, '2026-10-26 18:07:16', '2026-10-26 18:07:16'),
(4, '/contact-us', 'Contact & Clinic Locations', 'Book Appointment & Clinic Locations | Skinfinity Derma Noida & Gurgaon', 'Schedule your consultation with senior MD Dermatologists. Get clinic directions, phone numbers, WhatsApp, and consultation timings.', NULL, NULL, NULL, NULL, 'https://www.skinfinityderma.com/contact-us/', 'index,follow', NULL, 1, 0.8, 'monthly', 1, '2026-10-26 18:07:16', '2026-10-26 18:07:16');
