INSERT INTO `sid_services` (`id`, `category_id`, `name`, `slug`, `short_desc`, `full_desc`, `image`, `additional_images`, `benefits`, `procedure_steps`, `faqs`, `associated_treatment_ids`, `cta_text`, `cta_url`, `display_order`, `is_active`, `seo_title`, `seo_desc`, `created_at`, `updated_at`) VALUES
(5, 5, 'Acne & Pimple Treatment', 'acne-pimple-treatment', 'Acne & Pimple Treatment performed by board-certified senior dermatologists at Skinfinity Derma clinics in Noida and Gurgaon. Customized clinical protocols with US-FDA approved technology.', 'Experience visible, clinically-proven transformation with our doctor-led Acne & Pimple Treatment. Under the expert supervision of Dr. Ipshita Johri, our specialized medical dermatology protocol targets root causes with customized clinical energy, active serums, and strict sterilization standards. Ideal for patients seeking safe, radiant, and long-lasting results.', '/images/treatments/banner-acne.webp', NULL, '[\"US-FDA approved clinical protocol tailored by senior MD dermatologists.\",\"Zero downtime or minimal recovery with long-lasting aesthetic outcomes.\",\"Safe for Indian skin tones with personalized pre-and-post care guidance.\"]', '[{\"stepNumber\":\"01\",\"title\":\"Clinical Skin & Health Analysis\",\"desc\":\"Digital dermoscopy and doctor consultation to evaluate tissue depth and indications.\",\"image\":\"/images/treatments/banner-acne.webp\"},{\"stepNumber\":\"02\",\"title\":\"Targeted Cleansing & Prep\",\"desc\":\"Sterile pre-treatment medical prep and application of numbing cream if indicated.\",\"image\":\"/images/treatments/banner-acne.webp\"},{\"stepNumber\":\"03\",\"title\":\"Precision Clinical Protocol\",\"desc\":\"Execution of Acne & Pimple Treatment utilizing calibrated parameters for maximum safety.\",\"image\":\"/images/treatments/banner-acne.webp\"},{\"stepNumber\":\"04\",\"title\":\"Post-Treatment Soothing Infusion\",\"desc\":\"Cooling soothing barrier serum and broad-spectrum sunscreen application.\",\"image\":\"/images/treatments/banner-acne.webp\"},{\"stepNumber\":\"05\",\"title\":\"Doctor Review & Home Care Plan\",\"desc\":\"Detailed aftercare instructions and personalized skincare regimen.\",\"image\":\"/images/treatments/banner-acne.webp\"}]', '[{\"question\":\"How many sessions of Acne & Pimple Treatment are recommended?\",\"answer\":\"Most patients see initial improvement after just 1 session. For sustained and optimal clinical results, our dermatologists recommend a personalized protocol of 3 to 6 sessions spaced 3–4 weeks apart.\"},{\"question\":\"Is Acne & Pimple Treatment painful or uncomfortable?\",\"answer\":\"Our procedures are designed for maximum comfort. Depending on the modality, topical numbing or advanced cooling mechanisms are utilized to ensure the session is virtually painless.\"},{\"question\":\"Why choose Skinfinity Derma for Acne & Pimple Treatment?\",\"answer\":\"At Skinfinity Derma, every single protocol is planned and supervised by certified MD dermatologists using genuine US-FDA approved technology and hospital-grade sanitization.\"}]', NULL, 'Book Appointment', '/acne-pimple-treatment', 1, 1, 'Acne & Pimple Treatment in Noida & Gurgaon | Skinfinity Derma', 'Book Acne & Pimple Treatment with Dr. Ipshita Johri at Skinfinity Derma. US-FDA approved technologies, top dermatologists, and customized aesthetic results.', '2026-11-01 13:01:16', '2026-11-01 13:01:16'),
(6, 5, 'viscoderm', 'viscoderm', 'viscoderm performed by board-certified senior dermatologists at Skinfinity Derma clinics in Noida and Gurgaon. Customized clinical protocols with US-FDA approved technology.', 'Experience visible, clinically-proven transformation with our doctor-led viscoderm. Under the expert supervision of Dr. Ipshita Johri, our specialized medical dermatology protocol targets root causes with customized clinical energy, active serums, and strict sterilization standards. Ideal for patients seeking safe, radiant, and long-lasting results.', '/images/treatments/banner-acne.webp', NULL, '[\"US-FDA approved clinical protocol tailored by senior MD dermatologists.\",\"Zero downtime or minimal recovery with long-lasting aesthetic outcomes.\",\"Safe for Indian skin tones with personalized pre-and-post care guidance.\"]', '[{\"stepNumber\":\"01\",\"title\":\"Clinical Skin & Health Analysis\",\"desc\":\"Digital dermoscopy and doctor consultation to evaluate tissue depth and indications.\",\"image\":\"/images/treatments/banner-acne.webp\"},{\"stepNumber\":\"02\",\"title\":\"Targeted Cleansing & Prep\",\"desc\":\"Sterile pre-treatment medical prep and application of numbing cream if indicated.\",\"image\":\"/images/treatments/banner-acne.webp\"},{\"stepNumber\":\"03\",\"title\":\"Precision Clinical Protocol\",\"desc\":\"Execution of viscoderm utilizing calibrated parameters for maximum safety.\",\"image\":\"/images/treatments/banner-acne.webp\"},{\"stepNumber\":\"04\",\"title\":\"Post-Treatment Soothing Infusion\",\"desc\":\"Cooling soothing barrier serum and broad-spectrum sunscreen application.\",\"image\":\"/images/treatments/banner-acne.webp\"},{\"stepNumber\":\"05\",\"title\":\"Doctor Review & Home Care Plan\",\"desc\":\"Detailed aftercare instructions and personalized skincare regimen.\",\"image\":\"/images/treatments/banner-acne.webp\"}]', '[{\"question\":\"How many sessions of viscoderm are recommended?\",\"answer\":\"Most patients see initial improvement after just 1 session. For sustained and optimal clinical results, our dermatologists recommend a personalized protocol of 3 to 6 sessions spaced 3–4 weeks apart.\"},{\"question\":\"Is viscoderm painful or uncomfortable?\",\"answer\":\"Our procedures are designed for maximum comfort. Depending on the modality, topical numbing or advanced cooling mechanisms are utilized to ensure the session is virtually painless.\"},{\"question\":\"Why choose Skinfinity Derma for viscoderm?\",\"answer\":\"At Skinfinity Derma, every single protocol is planned and supervised by certified MD dermatologists using genuine US-FDA approved technology and hospital-grade sanitization.\"}]', NULL, 'Book Appointment', '/viscoderm', 2, 1, 'viscoderm in Noida & Gurgaon | Skinfinity Derma', 'Book viscoderm with Dr. Ipshita Johri at Skinfinity Derma. US-FDA approved technologies, top dermatologists, and customized aesthetic results.', '2026-11-01 13:01:16', '2026-11-01 13:01:16'),
